Load the cached values, scan column E for cells containing “Georgia Its Tax”, and replace them based on whether column F is a whole number. Clear column H in the data range and remove its fill. Save the workbook with plain values in the answer region.

```python
import shutil
import openpyxl
from openpyxl.styles import PatternFill

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

TARGET = "Georgia Its Tax"

def to_float(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        s = value.strip().replace("$", "").replace(",", "")
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None

def is_whole_number(value):
    if value is None:
        return False
    return abs(value - round(value)) < 1e-9

max_row = max(17, vws.max_row)
changed = []

for r in range(2, max_row + 1):
    e_val = vws.cell(row=r, column=5).value
    f_val = vws.cell(row=r, column=6).value

    new_e = e_val

    if isinstance(e_val, str) and TARGET in e_val:
        f_num = to_float(f_val)
        if f_num is not None:
            if is_whole_number(f_num):
                new_e = "Georgia WH Tax"
            else:
                new_e = "Georgia Sales Tax"
            changed.append((r, new_e))

    if isinstance(new_e, str):
        new_e = new_e.strip()

    ws.cell(row=r, column=5).value = new_e

none_fill = PatternFill(fill_type=None)
for r in range(1, max_row + 1):
    h_cell = ws.cell(row=r, column=8)
    h_cell.value = None
    h_cell.fill = none_fill

wb.save(OUT)

print("max_row:", max_row)
print("changed:", changed)
